# How many of WIPO's core articles exist in each of the four project languages?
# The list is the one on the project's tracking page (meta.wikimedia.org/wiki/WikiProject:United_Nations/WIPO);
# membership is read from Wikidata sitelinks, so a rename or a merge cannot silently make a language look empty.
SELECT ?Language (COUNT(DISTINCT ?item) AS ?Articles) WHERE {
  VALUES ?enTitle { "World Intellectual Property Organization"@en "Intellectual property"@en "Global Innovation Index"@en "World Intellectual Property Day"@en "World Intellectual Property Report"@en "World Intellectual Property Indicators"@en "WIPO Lex"@en "Patentscope"@en "Global Brand Database"@en "Global Design Database"@en "WIPO GREEN"@en "WIPO Judicial Institute"@en "Beijing Treaty on Audiovisual Performances"@en "Berne Convention"@en "Budapest Treaty"@en "Convention Relating to the Distribution of Programme-Carrying Signals Transmitted by Satellite"@en "Design Law Treaty"@en "Geneva Phonograms Convention"@en "Hague Agreement Concerning the International Deposit of Industrial Designs"@en "International (Nice) Classification of Goods and Services"@en "Lisbon Agreement for the Protection of Appellations of Origin and their International Registration"@en "Madrid Protocol"@en "Marrakesh VIP Treaty"@en "Nairobi Treaty on the Protection of the Olympic Symbol"@en "Paris Convention for the Protection of Industrial Property"@en "Patent Cooperation Treaty"@en "Patent Law Treaty"@en "Rome Convention for the Protection of Performers, Producers of Phonograms and Broadcasting Organisations"@en "Singapore Treaty on the Law of Trademarks"@en "Strasbourg Agreement Concerning the International Patent Classification"@en "Trademark Law Treaty of 1994"@en "Trade secret"@en "WIPO Copyright Treaty"@en "WIPO Hague System"@en "WIPO Performances and Phonograms Treaty"@en "Intergovernmental Committee on Intellectual Property and Genetic Resources, Traditional Knowledge and Folklore"@en "Patent"@en "Patent application"@en "Patent prosecution"@en "Industrial property"@en "Intangible asset"@en "Intangible asset finance"@en "Trademark"@en "Industrial designs"@en "Traditional knowledge"@en "Uniform Domain-Name Dispute-Resolution Policy"@en "Daren Tang"@en "Article 6ter"@en }
  ?enArt schema:about ?item ; schema:isPartOf <https://en.wikipedia.org/> ; schema:name ?enTitle .
  VALUES (?Language ?site) {
    ("English" <https://en.wikipedia.org/>)
    ("French" <https://fr.wikipedia.org/>)
    ("Spanish" <https://es.wikipedia.org/>)
    ("Arabic" <https://ar.wikipedia.org/>) }
  ?art schema:about ?item ; schema:isPartOf ?site .
} GROUP BY ?Language ORDER BY DESC(?Articles)

# The core articles, one row each, and the languages in which they exist.
# "yes" is a Wikidata sitelink — the same evidence the bar chart counts.
SELECT ?Article ?English ?French ?Spanish ?Arabic WHERE {
  VALUES ?enTitle { "World Intellectual Property Organization"@en "Intellectual property"@en "Global Innovation Index"@en "World Intellectual Property Day"@en "World Intellectual Property Report"@en "World Intellectual Property Indicators"@en "WIPO Lex"@en "Patentscope"@en "Global Brand Database"@en "Global Design Database"@en "WIPO GREEN"@en "WIPO Judicial Institute"@en "Beijing Treaty on Audiovisual Performances"@en "Berne Convention"@en "Budapest Treaty"@en "Convention Relating to the Distribution of Programme-Carrying Signals Transmitted by Satellite"@en "Design Law Treaty"@en "Geneva Phonograms Convention"@en "Hague Agreement Concerning the International Deposit of Industrial Designs"@en "International (Nice) Classification of Goods and Services"@en "Lisbon Agreement for the Protection of Appellations of Origin and their International Registration"@en "Madrid Protocol"@en "Marrakesh VIP Treaty"@en "Nairobi Treaty on the Protection of the Olympic Symbol"@en "Paris Convention for the Protection of Industrial Property"@en "Patent Cooperation Treaty"@en "Patent Law Treaty"@en "Rome Convention for the Protection of Performers, Producers of Phonograms and Broadcasting Organisations"@en "Singapore Treaty on the Law of Trademarks"@en "Strasbourg Agreement Concerning the International Patent Classification"@en "Trademark Law Treaty of 1994"@en "Trade secret"@en "WIPO Copyright Treaty"@en "WIPO Hague System"@en "WIPO Performances and Phonograms Treaty"@en "Intergovernmental Committee on Intellectual Property and Genetic Resources, Traditional Knowledge and Folklore"@en "Patent"@en "Patent application"@en "Patent prosecution"@en "Industrial property"@en "Intangible asset"@en "Intangible asset finance"@en "Trademark"@en "Industrial designs"@en "Traditional knowledge"@en "Uniform Domain-Name Dispute-Resolution Policy"@en "Daren Tang"@en "Article 6ter"@en }
  ?enArt schema:about ?item ; schema:isPartOf <https://en.wikipedia.org/> ; schema:name ?enTitle .
  BIND(?enTitle AS ?Article) BIND("yes" AS ?English)
  OPTIONAL { ?a schema:about ?item ; schema:isPartOf <https://fr.wikipedia.org/> . } BIND(IF(BOUND(?a), "yes", "—") AS ?French)
  OPTIONAL { ?b schema:about ?item ; schema:isPartOf <https://es.wikipedia.org/> . } BIND(IF(BOUND(?b), "yes", "—") AS ?Spanish)
  OPTIONAL { ?c schema:about ?item ; schema:isPartOf <https://ar.wikipedia.org/> . } BIND(IF(BOUND(?c), "yes", "—") AS ?Arabic)
} ORDER BY ?Article

# WIPO is Q177773 (verified; not the QID one would guess).
# P123 = publisher, P50 = author (WIPO is credited as author on some publications).
SELECT (COUNT(DISTINCT ?authored) AS ?authored) (COUNT(DISTINCT ?published) AS ?published) WHERE {
  OPTIONAL { ?authored wdt:P50 wd:Q177773 }
  OPTIONAL { ?published wdt:P123 wd:Q177773 }
}
